320	function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
321	  if (!rawCss) return "";
322	  // Sanitize the same way the public API does (mirrors api.widget-config.tsx)
323	  const css = rawCss
324	    .replace(/<style\b[^>]*>/gi, "")
325	    .replace(/<\/style>/gi, "")
326	    .replace(/@import\b[^;]*(;|$)/gi, "")
327	    .replace(/\bexpression\s*\(/gi, "")
328	    .replace(/url\s*\(\s*['"]?\s*javascript\s*:/gi, "url(")
329	    .replace(/url\s*\(\s*['"]?\s*data\s*:/gi, "url(");
330	  let result = "";
331	  let i = 0;
332	  while (i < css.length) {
333	    // Skip whitespace
334	    while (i < css.length && /\s/.test(css[i])) { result += css[i]; i++; }
335	    if (i >= css.length) break;
336	    // Handle at-rules
337	    if (css[i] === "@") {
338	      let atRule = "";
339	      let j = i;
340	      while (j < css.length && css[j] !== "{" && css[j] !== ";") { atRule += css[j]; j++; }
341	      const atName = atRule.trim().toLowerCase();
342	      // @keyframes and @font-face: pass through without scoping
343	      if (atName.startsWith("@keyframes") || atName.startsWith("@font-face")) {
344	        result += atRule;
345	        if (j < css.length && css[j] === "{") {
346	          let depth = 1; result += css[j]; j++;
347	          while (j < css.length && depth > 0) {
348	            if (css[j] === "{") depth++;
349	            if (css[j] === "}") depth--;
350	            result += css[j]; j++;
351	          }
352	        }
353	        i = j; continue;
354	      }
